def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not hasattr(self, '_record'):
        raise AttributeError("Record not initialized")

    if not keys:
        return list(self._record.values())

    result = []
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._record):
                raise IndexError("Index out of range")
            result.append(list(self._record.values())[key])
        elif isinstance(key, str):
            if key not in self._record:
                raise KeyError("Key not found")
            result.append(self._record[key])
        else:
            raise TypeError("Invalid key type")

    return result

def data(self, *keys):
    result = {}
    if not keys:
        for key, value in self.record.items():
            result[key] = value
    else:
        for key in keys:
            if isinstance(key, int):
                if key < 0 or key >= len(self.record):
                    raise IndexError("Out-of-bounds index specified")
                result[self.record.keys()[key]] = self.record.values()[key]
            elif isinstance(key, str):
                if key not in self.record:
                    result[key] = None
                else:
                    result[key] = self.record[key]
            else:
                raise TypeError("Invalid key type")
    return result

def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, rounding half to the nearest even number.

    :param n: The number to round.
    :return: The rounded number.
    """
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be an integer or float")

    if n >= 0:
        return int(n + 0.5) if n - int(n) != 0.5 else int(n) + (int(n) % 2)
    else:
        return int(n - 0.5) if n - int(n) != -0.5 else int(n) - (int(n) % 2)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    if not name or not isinstance(name, str):
        raise ValueError("Name must be a non-empty string")
    if not fields or not isinstance(fields, list):
        raise ValueError("Fields must be a non-empty list")
    if not srid_map or not isinstance(srid_map, dict):
        raise ValueError("SRID map must be a non-empty dictionary")

    try:
        # Define the Point subclass dynamically
        Point = type(name, (object,), {
            '__init__': lambda self, *args: super().__init__(*args),
            '__repr__': lambda self: f"{name}({', '.join([f'{field}={getattr(self, field)}' for field in fields])})"
        })

        # Add SRID map to the class
        Point.srid_map = srid_map

        return Point
    except Exception as e:
        raise RuntimeError(f"Failed to create Point subclass: {e}")

