def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(func):
        def wrapper(self, *args, **kwargs):
            if lock is not None:
                lock.acquire()
            try:
                cache_key = key(func, self, *args, **kwargs)
                if cache_key in cache:
                    return cache[cache_key]
                result = func(self, *args, **kwargs)
                cache[cache_key] = result
                return result
            finally:
                if lock is not None:
                    lock.release()
        return wrapper
    return decorator

def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        def format_traceback(tb, level=0):
            if level >= max_level:
                return "..."
            if tb is None:
                return ""
            return f"{tb.filename}:{tb.lineno} in {tb.name}\n" + format_traceback(tb.tb_next, level + 1)

        def format_path(path, level=0):
            if level >= max_path_level:
                return "..."
            if not path:
                return ""
            return f"{path[0]}\n" + format_path(path[1:], level + 1)

        try:
            return f"{e.__class__.__name__}: {e}\nTraceback:\n{format_traceback(e.__traceback__)}\nPath:\n{format_path(e.__traceback__.tb_frame.f_locals.get('self', None).__class__.__mro__)}"
        except Exception as ex:
            return f"Error formatting exception: {ex}"

