def _legacy_mergeOrderings(orderings):
    merged = []
    seen = set()
    for ordering in orderings:
        for item in ordering:
            if item not in seen:
                merged.append(item)
                seen.add(item)
    return merged

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Create a dictionary to store the inheritance relationships
    inheritance = {cls: set() for cls in classes}
    for cls in classes:
        for base in cls.__bases__:
            if base in classes:
                inheritance[cls].add(base)

    # Function to find the minimal bases for a given class
    def find_minimal_bases(cls):
        if not inheritance[cls]:
            return [cls]
        min_bases = []
        for base in inheritance[cls]:
            bases = find_minimal_bases(base)
            if not min_bases or len(bases) < len(min_bases):
                min_bases = bases
        return [cls] + min_bases

    # Find minimal bases for each class and remove duplicates
    minimal_bases = set()
    for cls in classes:
        minimal_bases.update(find_minimal_bases(cls))

    # Sort the minimal bases based on their order in the original list
    minimal_bases = sorted(minimal_bases, key=lambda x: classes.index(x))

    return minimal_bases

