def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    if not manifest_files or not digests_used:
        raise ValueError("Manifest files and digests used cannot be empty")

    for manifest_file in manifest_files:
        try:
            with open(manifest_file, 'r') as file:
                manifest_content = file.read()
                for digest in digests_used:
                    if digest not in manifest_content:
                        raise ValueError(f"Digest {digest} not found in manifest file {manifest_file}")
        except FileNotFoundError:
            raise FileNotFoundError(f"Manifest file {manifest_file} not found")
        except Exception as e:
            raise Exception(f"Error processing manifest file {manifest_file}: {e}")

    print("All required digests are present and used in the manifest files.")

def get_logical_path_map(inventory, version):
    logical_path_map = {}
    if version not in inventory:
        raise ValueError(f"Version {version} not found in inventory")
    for logical_path, file_info in inventory[version].items():
        if logical_path not in logical_path_map:
            logical_path_map[logical_path] = set()
        logical_path_map[logical_path].add(file_info['content_file'])
    return logical_path_map

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if not isinstance(manifest_files, list) or not all(isinstance(f, str) for f in manifest_files):
        raise ValueError("Manifest files must be a list of strings")

    valid_files = set(manifest_files)

    for file_info in fixity.values():
        if not isinstance(file_info, dict):
            raise ValueError("Each file info in fixity block must be a dictionary")

        file_name = file_info.get('file_name')
        if not isinstance(file_name, str) or file_name not in valid_files:
            raise ValueError(f"Invalid file name in fixity block: {file_name}")

        fixity_type = file_info.get('fixity_type')
        if not isinstance(fixity_type, str):
            raise ValueError("Fixity type must be a string")

        checksum = file_info.get('checksum')
        if not isinstance(checksum, str):
            raise ValueError("Checksum must be a string")

    return True

