def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for expr in args:
        if isinstance(expr, tuple) and len(expr) == 3 and expr[1] in ('&', '|'):
            a, op, b = expr
            if op == '&':
                if isinstance(b, tuple) and b[1] == '|':
                    if b[0] == a:
                        result.append(a)
                    elif b[2] == a:
                        result.append(a)
                    else:
                        result.append(expr)
                elif isinstance(b, tuple) and b[1] == '&':
                    if b[0] == a:
                        result.append(b[2])
                    elif b[2] == a:
                        result.append(b[0])
                    else:
                        result.append(expr)
                else:
                    result.append(expr)
            elif op == '|':
                if isinstance(b, tuple) and b[1] == '|':
                    if b[0] == a:
                        result.append(a)
                    elif b[2] == a:
                        result.append(a)
                    else:
                        result.append(expr)
                elif isinstance(b, tuple) and b[1] == '&':
                    if b[0] == a:
                        result.append(b[2])
                    elif b[2] == a:
                        result.append(b[0])
                    else:
                        result.append(expr)
                else:
                    result.append(expr)
        else:
            result.append(expr)
    return result

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
