    result = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in result:
            if isinstance(result[key], dict) and isinstance(value_node.value, dict):
                result[key] = deep_merge_nodes([(ScalarNode(tag='tag:yaml.org,2002:str', value=k), ScalarNode(tag='tag:yaml.org,2002:int', value=v)) for k, v in result[key].items()] + [(ScalarNode(tag='tag:yaml.org,2002:str', value=k), ScalarNode(tag='tag:yaml.org,2002:int', value=v)) for k, v in value_node.value.items()])
            else:
                result[key] = value_node.value
        else:
            result[key] = value_node.value
    return [(ScalarNode(tag='tag:yaml.org,2002:str', value=k), MappingNode(tag='tag:yaml.org,2002:map', value=[(ScalarNode(tag='tag:yaml.org,2002:str', value=k2), ScalarNode(tag='tag:yaml.org,2002:int', value=v2)) for k2, v2 in v.items()])) for k, v in result.items()]

