def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_args = {}
    remaining_args = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        subparser_args = []
        for arg in remaining_args:
            if arg.startswith(f"--{subparser_name}"):
                subparser_args.append(arg)
                remaining_args.remove(arg)
            else:
                break
        if subparser_args:
            parsed_args[subparser_name] = parser.parse_args(subparser_args)

    return parsed_args, remaining_args

def deep_merge_nodes(nodes):
    merged_dict = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key not in merged_dict:
            merged_dict[key] = value_node
        else:
            if isinstance(merged_dict[key], ruamel.yaml.nodes.MappingNode) and isinstance(value_node, ruamel.yaml.nodes.MappingNode):
                merged_dict[key] = deep_merge_nodes([(k, v) for k, v in zip(merged_dict[key].value, value_node.value)])
            else:
                merged_dict[key] = value_node
    return [(key_node, value_node) for key_node, value_node in merged_dict.items()]

