def parse_subparser_arguments(unparsed_arguments, subparsers):
    parsed_args = {}
    remaining_args = list(unparsed_arguments)

    for subparser_name, parser in subparsers.items():
        # Create a copy of the remaining arguments to avoid modifying the original list
        args_to_parse = remaining_args[:]
        # Attempt to parse the arguments using the current subparser
        namespace, remaining = parser.parse_known_args(args_to_parse)
        # If any arguments were parsed, update the parsed_args dictionary
        if namespace:
            parsed_args[subparser_name] = namespace
            # Remove the parsed arguments from the remaining list
            remaining_args = [arg for arg in remaining_args if arg not in args_to_parse]

    return parsed_args, remaining_args

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.upper()
    if size.endswith('B'):
        return int(size[:-1])
    elif size.endswith('K'):
        return int(float(size[:-1]) * 1000)
    elif size.endswith('M'):
        return int(float(size[:-1]) * 1000000)
    elif size.endswith('G'):
        return int(float(size[:-1]) * 1000000000)
    elif size.endswith('T'):
        return int(float(size[:-1]) * 1000000000000)
    else:
        raise ValueError("Invalid size format")

