def load_configurations(config_filenames: List[str], overrides: Dict[str, str] = None, resolve_env: bool = True) -> Tuple[Dict[str, dict], List[logging.LogRecord]]:
    if overrides is None:
        overrides = {}

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = eval(file.read(), overrides)
                if resolve_env:
                    config = resolve_environment_variables(config)
                config_dict[filename] = config
        except Exception as e:
            log_record = logging.LogRecord(name='load_configurations', level=logging.ERROR, pathname=filename, lineno=0, msg=str(e), args=(), exc_info=None)
