def scale(self, other=None, recompute=False):
    if other is None:
        if not hasattr(self, '_scale') or recompute:
            self._scale = sum(self._histogram)
        return self._scale
    else:
        if self._scale == 0:
            raise LenaValueError("Can't rescale histogram with scale equal to zero")
        self._histogram = [x * (other / self._scale) for x in self._histogram]
        self._scale = other

def scale(self, other=None):
    if other is None:
        return self._scale
    elif isinstance(other, (int, float)):
        if self._scale == 0 or self._scale is None:
            raise LenaValueError("Cannot rescale graph with unknown or zero scale")
        self._scale = other
        for field in self._fields:
            if field[-1] == self._scale:
                field[-1] = other
    else:
        raise TypeError("Invalid input type for rescaling")

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_content: bin_content

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("Invalid get_coordinate value. Must be 'left', 'right', or 'middle'.")

    if len(field_names) != 2:
        raise ValueError("Invalid number of field_names. Must be 2.")

    if scale is not None and scale not in [True, False]:
        raise ValueError("Invalid scale value. Must be True or False.")

    graph_points = []
    for bin_index, bin_content in enumerate(hist.bins):
        if make_value(bin_content) is None:
            continue

        if get_coordinate == "left":
            coordinate = bin_index
        elif get_coordinate == "right":
            coordinate = bin_index + 1
        elif get_coordinate == "middle":
            coordinate = bin_index + 0.5

        graph_point = {field_names[0]: coordinate, field_names[1]: make_value(bin_content)}
        graph_points.append(graph_point)

    if scale is True:
        graph_scale = hist.scale
    else:
        graph_scale = None

    return graph_points, graph_scale

def _verify(iface, candidate, tentative=False, vtype=None):
    from zope.interface import Invalid, implementer, provider, providedBy

    if not tentative and not providedBy(candidate, iface):
        raise Invalid(f"Candidate does not claim to provide interface {iface}")

    candidate_methods = set(dir(candidate))
    required_methods = set(iface.names())
    missing_methods = required_methods - candidate_methods

    if missing_methods:
        raise Invalid(f"Missing methods: {', '.join(missing_methods)}")

    for method_name in required_methods:
        method = getattr(candidate, method_name)
        if not callable(method):
            raise Invalid(f"Method {method_name} is not callable")

    candidate_attributes = set(dir(candidate))
    required_attributes = set(iface.names())
    missing_attributes = required_attributes - candidate_attributes

    if missing_attributes:
        raise Invalid(f"Missing attributes: {', '.join(missing_attributes)}")

    return True

def verifyObject(iface, candidate, tentative=False):
    from zope.interface import Invalid, implementer, provider, providedBy, implementedBy

    if not tentative and not providedBy(candidate, iface):
        raise Invalid(f"Candidate does not claim to provide interface {iface}")

    candidate_iface = implementedBy(candidate)
    if iface not in candidate_iface:
        raise Invalid(f"Candidate does not implement interface {iface}")

    candidate_methods = set(dir(candidate))
    required_methods = set(iface.names())
    missing_methods = required_methods - candidate_methods
    if missing_methods:
        raise Invalid(f"Candidate is missing methods: {', '.join(missing_methods)}")

    for method_name in required_methods:
        method = getattr(candidate, method_name)
        if not callable(method):
            raise Invalid(f"Candidate method {method_name} is not callable")

    candidate_attributes = set(dir(candidate))
    required_attributes = set(iface.names())
    missing_attributes = required_attributes - candidate_attributes
    if missing_attributes:
        raise Invalid(f"Candidate is missing attributes: {', '.join(missing_attributes)}")

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not hasattr(candidate, '__dict__'):
        return False

    for attr in iface.__dict__:
        if not tentative and attr.startswith('__'):
            continue
        if attr not in candidate.__dict__:
            return False
        if not callable(getattr(iface, attr)) and getattr(iface, attr) != getattr(candidate, attr):
            return False
        if callable(getattr(iface, attr)) and not callable(getattr(candidate, attr)):
            return False
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    for base in bases:
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__

    return type

def pop(self, key, default=__marker):
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")

    # Assuming self is a dictionary where values are lists of frequencies
    min_freq = min(self.values(), key=lambda x: x[0])
    for key, value in self.items():
        if value[0] == min_freq:
            del self[key]
            return (key, value[1])

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    key, value = self.popitem()
    return key, value

