from typing import Set, Tuple

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    in_code_block = False
    result = []
    current_tag = []

    for char in text:
        if char == '`':
            in_code_block = not in_code_block
        elif not in_code_block:
            if char == '<':
                current_tag.append(char)
            elif char == '>':
                current_tag.append(char)
                tag = ''.join(current_tag)
                tags.add(tag)
                current_tag = []
            elif current_tag:
                current_tag.append(char)

    if replacer:
        result_text = ''.join(replacer(tag[1:-1]) if tag.startswith('<') and tag.endswith('>') else tag for tag in text.split('<') if '>' in tag)
    else:
        result_text = text

    return tags, result_text

